"""Draws the Trax .NET mark, its lockups and the icon in .github/brand.

    pip install fonttools
    python3 .github/brand/draw.py .github/brand path/to/JetBrainsMono-Bold.ttf

The mark is a route: a line from state A through state B to state C, the one it reached. The
wordmark is JetBrains Mono Bold (SIL Open Font License), converted to outlines here so nothing
that shows the logo needs the font. Edit the mark here and rerun; do not edit the SVGs. The PNG
and ICO files are rendered from icon.svg; README.md in this folder has the commands.
"""
import os
import sys

from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
from fontTools.ttLib import TTFont

OUT, FONT = sys.argv[1], sys.argv[2]

GREEN = "#1f5f41"          # on light backgrounds
GREEN_ON_DARK = "#6cc596"  # on dark backgrounds
ICON_INK = "#eef6f1"       # the mark inside the icon tile


def mark(color, mid="m"):
    """The route, in a 100 x 100 box. The open stations are holes cut by the mask."""
    return (
        f'<mask id="{mid}"><rect width="100" height="100" fill="#fff"/>'
        '<circle cx="20" cy="80" r="4.5" fill="#000"/><circle cx="50" cy="56" r="4" fill="#000"/></mask>'
        f'<g mask="url(#{mid})" fill="{color}">'
        f'<path d="M20 80 C20 54 80 60 80 24" fill="none" stroke="{color}" stroke-width="7" stroke-linecap="round"/>'
        '<circle cx="20" cy="80" r="10"/><circle cx="50" cy="56" r="9"/><circle cx="80" cy="24" r="13"/></g>'
    )


font = TTFont(FONT)
glyphs = font.getGlyphSet()
cmap = font.getBestCmap()
upem = font["head"].unitsPerEm


def text_path(s, x, baseline, size):
    """The outline of s set at size, starting at x on baseline, and the x where it ends."""
    scale = size / upem
    pen = SVGPathPen(glyphs)
    for ch in s:
        name = cmap[ord(ch)]
        glyphs[name].draw(TransformPen(pen, (scale, 0, 0, -scale, x, baseline)))
        x += glyphs[name].width * scale
    return pen.getCommands(), x


def svg(w, h, body, title):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w:g} {h:g}" width="{w:g}" height="{h:g}" '
            f'role="img" aria-label="{title}"><title>{title}</title>{body}</svg>\n')


def write(name, content):
    with open(os.path.join(OUT, name), "w") as f:
        f.write(content)


write("mark.svg", svg(100, 100, mark(GREEN), "Trax .NET"))
write("mark-on-dark.svg", svg(100, 100, mark(GREEN_ON_DARK), "Trax .NET"))

# The lockup: the mark, then "Trax" and a lighter ".NET" on one baseline.
SIZE, BASELINE = 82, 80
trax, end = text_path("Trax", 116, BASELINE, SIZE)
net, end = text_path(".NET", end + 8, BASELINE, SIZE * 0.47)
width = end + 4
for name, color in [("lockup.svg", GREEN), ("lockup-on-dark.svg", GREEN_ON_DARK)]:
    body = (mark(color) + f'<path d="{trax}" fill="{color}"/>'
            f'<path d="{net}" fill="{color}" fill-opacity="0.6"/>')
    write(name, svg(width, 100, body, "Trax .NET"))

# The icon: the mark on a green tile, for favicons, the NuGet packages and avatars. The square
# one is for platforms that round the corners themselves (Apple's touch icon).
for name, rx in [("icon.svg", 22), ("icon-square.svg", 0)]:
    write(name, svg(100, 100,
          f'<rect width="100" height="100" rx="{rx}" fill="{GREEN}"/>'
          f'<g transform="translate(9 9) scale(0.82)">{mark(ICON_INK)}</g>', "Trax .NET"))

# The site draws the lockup inline, in currentColor, so the header and footer can colour it.
TSX = f"""// Generated by .github/brand/draw.py. Edit the mark there and rerun; do not edit this file.
/**
 * The Trax .NET lockup: the route mark, "Trax" and ".NET", in the current text colour. Each
 * instance on a page needs its own maskId, which cuts the open stations out of the mark.
 */
export default function TraxLogo({{ className, maskId }}: {{ className?: string; maskId: string }}) {{
  const mask = `trax-logo-${{maskId}}`;
  return (
    <svg viewBox="0 0 {width:g} 100" className={{className}} role="img" aria-label="Trax .NET">
      <mask id={{mask}}>
        <rect width="100" height="100" fill="#fff" />
        <circle cx="20" cy="80" r="4.5" fill="#000" />
        <circle cx="50" cy="56" r="4" fill="#000" />
      </mask>
      <g mask={{`url(#${{mask}})`}} fill="currentColor">
        <path d="M20 80 C20 54 80 60 80 24" fill="none" stroke="currentColor" strokeWidth="7" strokeLinecap="round" />
        <circle cx="20" cy="80" r="10" />
        <circle cx="50" cy="56" r="9" />
        <circle cx="80" cy="24" r="13" />
      </g>
      <path d="{trax}" fill="currentColor" />
      <path d="{net}" fill="currentColor" fillOpacity="0.6" />
    </svg>
  );
}}
"""
site = os.path.join(OUT, "..", "..", "Trax.Website", "src", "components", "layout", "TraxLogo.tsx")
with open(site, "w") as f:
    f.write(TSX)
